bool extract_socket_info(struct pool *pool, char *url) {
    char *start = url;
    char *end = NULL;
    char *port_start = NULL;
    char *address = NULL;
    size_t address_len = 0;
    int port = 0;
    bool success = false;

    // Check for IPv6 address enclosed in brackets
    if (*start == '[') {
        start++;
        end = strchr(start, ']');
        if (!end) {
            return false;
        }
        port_start = strchr(end, ':');
        if (port_start) {
            *port_start++ = '\0';
        }
        address = start;
        address_len = end - start;
    } else {
        // Regular IPv4 or hostname
        end = strchr(start, ':');
        if (end) {
            *end++ = '\0';
            port_start = end;
        }
        address = start;
        address_len = end ? (size_t)(end - start) : strlen(start);
    }

    // Check if address length is valid
    if (address_len > MAX_ADDRESS_LENGTH) {
        address[MAX_ADDRESS_LENGTH] = '\0';
        address_len = MAX_ADDRESS_LENGTH;
    }

    // Copy the address into the pool
    pool->address = malloc(address_len + 1);
    if (!pool->address) {
        return false;
    }
    strncpy(pool->address, address, address_len);
    pool->address[address_len] = '\0';

    // Parse port if provided
    if (port_start) {
        port = atoi(port_start);
    }

    // Set default port if none specified
    if (port == 0) {
        port = DEFAULT_PORT;
    }
    pool->port = port;

    success = true;
    return success;
}

bool extract_socket_address_from_url(struct pool *pool, char *url) {
    char *start = url;
    char *end = NULL;
    char *port_start = NULL;
    char *address = NULL;
    size_t address_len = 0;
    unsigned short port = 0;

    if (!url || !pool) {
        return false;
    }

    // Skip until the start of the URL (e.g., skip protocol)
    while (*start && *start != '/') {
        start++;
    }

    // IPv6 addresses are wrapped in brackets
    if (*start == '[') {
        start++;
        end = strchr(start, ']');
        if (!end) {
            return false;
        }

        address_len = end - start;
        address = pool_alloc(pool, address_len + 1);
        if (!address) {
            return false;
        }

        // Copy IPv6 address without the brackets
        strncpy(address, start, address_len);
        address[address_len] = '\0';
        port_start = strchr(end, ':');
    } else {
        end = start + strlen(start);
        address_len = end - start;
        address = pool_alloc(pool, address_len + 1);
        if (!address) {
            return false;
        }

        // Copy IPv4 or host name
        strncpy(address, start, address_len);
        address[address_len] = '\0';

        // Check for port
        port_start = strchr(address, ':');
        if (port_start) {
            *port_start = '\0';
            port_start++;
            if (strlen(port_start) > 0) {
                char *endptr = NULL;
                port = (unsigned short)strtol(port_start, &endptr, 10);
                if (endptr == port_start || *endptr != '\0') {
                    return false;
                }
            } else {
                port = 0;
            }
        } else {
            port = 0;
        }
    }

    if (address_len > 0) {
        pool->address = address;
        pool->port = port;
        return true;
    }

    return false;
}

