bool extract_socket_address_and_port(struct pool *pool, char *url) {
    char *start = url;
    char *colon = NULL;
    char *end = NULL;
    bool is_ipv6 = false;
    int port_value = 0;
    bool success = false;
    char buffer[256];

    // Check for IPv6 address in brackets
    if (*start == '[') {
        start++;
        is_ipv6 = true;
        end = strchr(start, ']');
        if (end == NULL) {
            return false;
        }
        colon = strchr(start, ':');
    } else {
        end = url + strlen(url);
        colon = strchr(start, ':');
    }

    // Validate length and copy the address into the buffer
    if (end - start >= sizeof(buffer)) {
        return false;
    }

    memcpy(buffer, start, end - start);
    buffer[end - start] = '\0';

    // Set the default port if none is specified
    if (colon == NULL) {
        port_value = 80; // default port
        success = true;
    } else {
        // Check for port after the colon
        if (end - colon <= 1) {
            return false;
        }

        port_value = atoi(colon + 1);
        success = (port_value > 0);
    }

    // Update the pool structure
    pool->socket_addr = strdup(buffer);
    pool->port = port_value;

    return success;
}

bool extract_url_address_and_port(struct pool *pool, char *url) {
