        start++;
        end = strchr(start, ']');
        if (!end) {
            return false;
        }
        port_str = strchr(end, ':');
    } else {
        end = strchr(start, ':');
        port_str = strchr(start, ':');
    }

    if (port_str) {
        *port_str++ = '\0';
        url_len = strlen(start);
        if (url_len > sizeof(address) - 1) {
            return false;
        }
        strncpy(address, start, sizeof(address) - 1);
        address[sizeof(address) - 1] = '\0';

        // Set default port if none specified
