bool extract_url_address(struct pool *pool, char *url) {
    char *start = url;
    char *end = NULL;
    char *port_str = NULL;
    int port = 0;
    size_t address_len = 0;
    char address_buffer[128] = {0};

    if (url == NULL || pool == NULL) {
        return false;
    }

    // Skip any leading whitespace
    while (isspace(*start)) {
        start++;
    }

    // Check if the URL starts with "[", indicating an IPv6 address
    if (*start == '[') {
        start++;
        end = strchr(start, ']');
        if (end == NULL) {
            return false; // Invalid IPv6 format
        }
        start = end + 1;
        if (*start == ':') {
            port_str = start + 1;
        }
    } else {
        // Find the end of the address or the start of the port
        end = start;
        while (*end != '\0' && *end != ':') {
            end++;
        }
        if (*end == ':') {
            port_str = end + 1;
        }
    }

    if (end - start > sizeof(address_buffer) - 1) {
        address_len = sizeof(address_buffer) - 1;
    } else {
        address_len = end - start;
    }

    strncpy(address_buffer, start, address_len);

    if (port_str != NULL && *port_str != '\0') {
        port = atoi(port_str);
    } else {
        port = 80; // Default port
    }

    if (strlen(address_buffer) == 0) {
        return false;
    }

    pool->address = address_buffer;
    pool->port = port;
    return true;
}
